export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  content: string;
  html: string;
  sourcePath: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

export interface ParsedFrontmatter {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

import { ParsedFrontmatter } from './types';

const DELIMITER = '---';

/**
 * Extract a `---`-delimited YAML frontmatter block from the top of a file.
 * Returns the raw YAML string (without delimiters) or null when absent.
 */
export function extractFrontmatterBlock(raw: string): string | null {
  if (!raw.startsWith(DELIMITER)) {
    return null;
  }
  const firstLineEnd = raw.indexOf('\n');
  if (firstLineEnd === -1) {
    return null;
  }
  const secondDelimiter = raw.indexOf(DELIMITER, firstLineEnd + 1);
  if (secondDelimiter === -1) {
    return null;
  }
  const block = raw.slice(firstLineEnd + 1, secondDelimiter);
  return block;
}

/**
 * Parse a `---`-delimited YAML frontmatter block.
 *
 * YAML frontmatter is unsupported by gray-matter out of the box, so we parse
 * the block ourselves with a simple `key: value` splitter. Scalars (strings,
 * numbers, booleans), dates, and simple comma-separated lists are supported.
 */
export function parseFrontmatter(raw: string): ParsedFrontmatter {
  const block = extractFrontmatterBlock(raw);
  if (block === null) {
    return {};
  }
  return parseYamlBlock(block);
}

/** Parse a plain `key: value` YAML block into a record. */
export function parseYamlBlock(block: string): ParsedFrontmatter {
  const data: ParsedFrontmatter = {};
  for (const rawLine of block.split('\n')) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) {
      continue;
    }
    const match = /^([A-Za-z0-9_.-]+)\s*:\s*(.*)$/.exec(line);
    if (!match) {
      continue;
    }
    const key = match[1];
    const value = parseYamlValue(match[2].trim());
    data[key] = value;
  }
  return data;
}

function parseYamlValue(raw: string): unknown {
  if (raw === '') {
    return '';
  }
  if (raw.startsWith('[') && raw.endsWith(']')) {
    const inner = raw.slice(1, -1);
    if (inner.trim() === '') {
      return [];
    }
    return inner
      .split(',')
      .map((item) => item.trim())
      .map(parseYamlValue);
  }
  if (raw.startsWith('"') && raw.endsWith('"')) {
    return raw.slice(1, -1);
  }
  if (raw.startsWith("'") && raw.endsWith("'")) {
    return raw.slice(1, -1);
  }
  if (raw === 'true') {
    return true;
  }
  if (raw === 'false') {
    return false;
  }
  if (/^\d+$/.test(raw)) {
    return parseInt(raw, 10);
  }
  if (/^\d+\.\d+$/.test(raw)) {
    return parseFloat(raw);
  }
  return raw;
}

import matter from 'gray-matter';
import { marked } from 'marked';
import { parseFrontmatter } from './frontmatter';
import { Page, ParsedFrontmatter } from './types';

/**
 * Parse a Markdown source string into structured page data.
 *
 * gray-matter only parses JSON frontmatter, so we parse the `---`-delimited
 * YAML block ourselves and merge it into gray-matter's output before handing
 * the data to the renderer.
 */
export function parseMarkdown(source: string, sourcePath: string, slug: string): Page {
  const yamlData = parseFrontmatter(source);
  const gm = matter(source);
  const merged: ParsedFrontmatter = { ...(gm.data as ParsedFrontmatter), ...yamlData };

  const title = readString(merged.title) || slug;
  const date = readString(merged.date);
  const tags = readTags(merged.tags);

  const html = marked.parse(gm.content, { async: false }) as string;

  return {
    slug,
    title,
    date,
    tags,
    content: gm.content,
    html,
    sourcePath,
  };
}

function readString(value: unknown): string | undefined {
  if (typeof value === 'string' && value.trim() !== '') {
    return value;
  }
  if (value instanceof Date) {
    return value.toISOString();
  }
  return undefined;
}

function readTags(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value
      .map((tag) => String(tag).trim())
      .filter((tag) => tag.length > 0);
  }
  if (typeof value === 'string' && value.trim() !== '') {
    return value
      .split(',')
      .map((tag) => tag.trim())
      .filter((tag) => tag.length > 0);
  }
  return [];
}

import { Page } from './types';

export function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function formatDate(date: string | undefined): string {
  if (!date) {
    return '';
  }
  const d = new Date(date);
  if (Number.isNaN(d.getTime())) {
    return date;
  }
  return d.toISOString().slice(0, 10);
}

export function renderPageHtml(page: Page): string {
  const title = escapeHtml(page.title);
  const date = formatDate(page.date);
  const dateLine = date ? `<p class="page-date">${escapeHtml(date)}</p>` : '';
  const tags = page.tags
    .map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`)
    .join(' ');
  const tagsLine = tags ? `<p class="page-tags">${tags}</p>` : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${title}</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 48rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.6; }
    a { color: #1a73e8; }
    .tag { background: #eef1f5; border-radius: 4px; padding: 0.1rem 0.5rem; margin-right: 0.25rem; }
  </style>
</head>
<body>
  <nav><a href="index.html">&larr; Home</a></nav>
  <article>
    <h1>${title}</h1>
    ${dateLine}
    ${tagsLine}
    <div class="content">
${page.html}
    </div>
  </article>
</body>
</html>
`;
}

export function renderIndexHtml(pages: Page[]): string {
  const sorted = [...pages].sort((a, b) => {
    const ad = a.date ? new Date(a.date).getTime() : 0;
    const bd = b.date ? new Date(b.date).getTime() : 0;
    return bd - ad;
  });

  const items = sorted
    .map((page) => {
      const date = formatDate(page.date);
      const datePart = date ? `<span class="date">${escapeHtml(date)}</span> ` : '';
      const tags = page.tags
        .map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`)
        .join(' ');
      const tagsPart = tags ? ` ${tags}` : '';
      return `<li>${datePart}<a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.title)}</a>${tagsPart}</li>`;
    })
    .join('\n    ');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Index</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 48rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.6; }
    a { color: #1a73e8; }
    .tag { background: #eef1f5; border-radius: 4px; padding: 0.1rem 0.5rem; margin-right: 0.25rem; }
    .date { color: #666; }
  </style>
</head>
<body>
  <h1>Index</h1>
  <ul>
    ${items}
  </ul>
</body>
</html>
`;
}

import { promises as fs } from 'fs';
import * as path from 'path';
import { parseMarkdown } from './markdown';
import { renderIndexHtml, renderPageHtml } from './render';
import { BuildOptions, Page } from './types';

const CONTENT_EXTENSIONS = ['.md', '.markdown', '.mdown'];

function slugify(filename: string): string {
  const base = filename.replace(/\.(md|markdown|mdown)$/i, '');
  return base
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

async function collectMarkdownFiles(
  dir: string,
  baseDir: string
): Promise<string[]> {
  const entries = await fs.readdir(dir, { withFileTypes: true });
  const files: string[] = [];
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await collectMarkdownFiles(full, baseDir)));
    } else if (entry.isFile() && CONTENT_EXTENSIONS.includes(path.extname(entry.name).toLowerCase())) {
      files.push(full);
    }
  }
  return files;
}

function makeSlug(file: string, contentDir: string): string {
  const rel = path.relative(contentDir, file);
  const parsed = path.parse(rel);
  const joined = parsed.dir ? path.join(parsed.dir, parsed.name) : parsed.name;
  return slugify(joined.replace(/\\/g, '/'));
}

async function readPages(contentDir: string): Promise<Page[]> {
  if (!(await dirExists(contentDir))) {
    throw new Error(`content directory not found: ${contentDir}`);
  }
  const files = await collectMarkdownFiles(contentDir, contentDir);
  files.sort();
  const pages: Page[] = [];
  for (const file of files) {
    const source = await fs.readFile(file, 'utf8');
    pages.push(parseMarkdown(source, file, makeSlug(file, contentDir)));
  }
  return pages;
}

async function dirExists(dir: string): Promise<boolean> {
  try {
    const stat = await fs.stat(dir);
    return stat.isDirectory();
  } catch {
    return false;
  }
}

export async function build(options: BuildOptions): Promise<Page[]> {
  const { contentDir, outputDir } = options;
  const pages = await readPages(contentDir);
  await fs.mkdir(outputDir, { recursive: true });

  for (const page of pages) {
    const html = renderPageHtml(page);
    await fs.writeFile(path.join(outputDir, `${page.slug}.html`), html, 'utf8');
  }

  const indexHtml = renderIndexHtml(pages);
  await fs.writeFile(path.join(outputDir, 'index.html'), indexHtml, 'utf8');

  return pages;
}

import { build } from './generator';
import { BuildOptions } from './types';

const DEFAULT_CONTENT_DIR = 'content';
const DEFAULT_OUTPUT_DIR = 'dist';

export interface CliArgs {
  command: string;
  options: BuildOptions;
}

function usage(): string {
  return `Usage: ssg build [--content <dir>] [--output <dir>]

Build a static site from Markdown files.

Options:
  --content <dir>  Content directory containing Markdown files (default: ./content)
  --output <dir>   Output directory for generated HTML (default: ./dist)
  --help           Show this help message`;
}

export function parseArgs(argv: string[]): CliArgs {
  const command = argv[0] || 'build';
  const options: BuildOptions = {
    contentDir: DEFAULT_CONTENT_DIR,
    outputDir: DEFAULT_OUTPUT_DIR,
  };

  for (let i = 1; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--content') {
      options.contentDir = argv[++i];
      if (!options.contentDir) {
        throw new Error('--content requires a directory argument');
      }
    } else if (arg === '--output') {
      options.outputDir = argv[++i];
      if (!options.outputDir) {
        throw new Error('--output requires a directory argument');
      }
    } else if (arg === '--help' || arg === '-h') {
      throw new HelpError(usage());
    } else {
      throw new Error(`unknown argument: ${arg}`);
    }
  }

  return { command, options };
}

export class HelpError extends Error {}

export async function main(argv: string[]): Promise<void> {
  const { command, options } = parseArgs(argv);

  if (command !== 'build') {
    throw new Error(`unknown command: ${command}`);
  }

  const pages = await build(options);
  process.stdout.write(
    `Built ${pages.length} page${pages.length === 1 ? '' : 's'} into ${options.outputDir}\n`
  );
}

import { main, HelpError } from './cli';

main(process.argv.slice(2)).catch((err: unknown) => {
  if (err instanceof HelpError) {
    process.stderr.write(`${err.message}\n`);
    process.exit(0);
  }
  const message = err instanceof Error ? err.message : String(err);
  process.stderr.write(`Error: ${message}\n`);
  process.exit(1);
});

export { parseMarkdown } from './markdown';
export { build } from './generator';
export { parseFrontmatter, parseYamlBlock } from './frontmatter';
export { renderIndexHtml, renderPageHtml } from './render';
export { parseArgs, main, HelpError } from './cli';
export type { Page, BuildOptions, ParsedFrontmatter } from './types';

import { extractFrontmatterBlock, parseFrontmatter, parseYamlBlock } from '../src/frontmatter';

describe('extractFrontmatterBlock', () => {
  it('extracts a YAML block delimited by ---', () => {
    const raw = '---\ntitle: Hello\ndate: 2024-01-02\n---\n# Body';
    expect(extractFrontmatterBlock(raw)).toBe('title: Hello\ndate: 2024-01-02');
  });

  it('returns null when the file has no frontmatter', () => {
    expect(extractFrontmatterBlock('# Just a heading')).toBeNull();
  });

  it('returns null when there is no closing delimiter', () => {
    expect(extractFrontmatterBlock('---\ntitle: Hello\n# Body')).toBeNull();
  });
});

describe('parseYamlBlock', () => {
  it('parses scalar values', () => {
    const data = parseYamlBlock('title: My Title\ndate: 2024-01-02');
    expect(data.title).toBe('My Title');
    expect(data.date).toBe('2024-01-02');
  });

  it('parses booleans and numbers', () => {
    const data = parseYamlBlock('draft: true\nrating: 5\npi: 3.14');
    expect(data.draft).toBe(true);
    expect(data.rating).toBe(5);
    expect(data.pi).toBe(3.14);
  });

  it('parses comma-separated lists', () => {
    const data = parseYamlBlock('tags: a, b, c');
    expect(data.tags).toEqual(['a', 'b', 'c']);
  });

  it('parses bracket lists', () => {
