    expect(html).not.toContain('<b>Title</b>');
    expect(html).toContain('A &lt;b&gt;Title&lt;/b&gt; &amp; more');
  });

  it('renders tags', () => {
    const html = renderPageHtml(makePage({ tags: ['tech', 'web'] }));
    expect(html).toContain('>tech<');
    expect(html).toContain('>web<');
  });
});

